import os
import subprocess
import threading
import time
from collections import defaultdict
from hashlib import sha256
from typing import Dict, List, Optional, Tuple

def compute_delay_ms(job: Dict, job_fields: Dict[str, int]) -> int:
    expr = job["delay"]
    for key, value in job_fields.items():
        expr = expr.replace(f"{{{{{key}}}}}", str(value))
    try:
        return int(expr)
    except ValueError:
        return 0

def generate_content_id(command: str) -> str:
    return sha256(command.encode()).hexdigest()[:32].lower()

def run_job(job: Dict, job_fields: Dict[str, int], cache: Dict[str, Dict]) -> Dict:
