import argparse
import json
import os
import subprocess
import threading
import time
from collections import deque
from typing import Dict, List, Optional, Tuple

def parse_delay(delay_str: str, job_vars: Dict[str, int]) -> int:
    import re
    def replace_match(match):
        expr = match.group(1)
        try:
            return str(eval(expr, {}, job_vars))
        except:
            return "0"
    return int(re.sub(r'\{\{(\w+)\}\}', replace_match, delay_str))

def generate_content_id(command: str) -> str:
    return command.encode('utf-8').hex()[:32].lower()

def run_job(job: Dict[str, str], job_vars: Dict[str, int], cache: Dict[str, Dict[str, str]]) -> Dict[str, str]:
    content_id = generate_content_id(job['command'])
    if content_id in cache:
        return {
            'id': job['id'],
            'command': job['command'],
            'delay_ms': 0,
            'exit_code': cache[content_id]['exit_code'],
            'output': cache[content_id]['output'],
            'content_id': content_id
        }

    delay_ms = parse_delay(job['delay'], job_vars)
    command = job['command']

    start_time = time.time()
    try:
        result = subprocess.run(
            command,
            shell=True,
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        exit_code = result.returncode
        output = result.stdout + result.stderr
    except subprocess.CalledProcessError as e:
        exit_code = e.returncode
        output = e.stdout + e.stderr
    except Exception as e:
        exit_code = 1
        output = f"Error: {str(e)}"

    cache[content_id] = {
        'exit_code': exit_code,
        'output': output
    }

    return {
        'id': job['id'],
        'command': job['command'],
        'delay_ms': int((time.time() - start_time) * 1000),
        'exit_code': exit_code,
        'output': output,
        'content_id': content_id
    }

def load_cache() -> Dict[str, Dict[str, str]]:
    cache_path = 'job_cache.json'
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            return json.load(f)
    return {}

def save_cache(cache: Dict[str, Dict[str, str]]) -> None:
    cache_path = 'job_cache.json'
    with open(cache_path, 'w') as f:
        json.dump(cache, f)

def process_jobs(jobs: List[Dict[str, str]], max_concurrent: int = 4, rate_limit_window_ms: int = 1000) -> List[Dict[str, str]]:
    cache = load_cache()
    job_queue = deque()
    active_jobs = []
    last_start_time = 0
    rate_limit_queue = deque()

    for job in jobs:
        job_vars = {k: int(v) for k, v in job.items() if isinstance(v, str) and k != 'command' and k != 'delay'}
        job_queue.append((job, job_vars))

    while job_queue or active_jobs:
        if not active_jobs and job_queue:
            job, job_vars = job_queue.popleft()
            job_start_time = time.time()
            active_jobs.append(threading.Thread(
                target=lambda: process_job(job, job_vars, cache)
            ))
            active_jobs[-1].start()

        if active_jobs:
            current_time = time.time()
            for i, thread in enumerate(active_jobs):
                if not thread.is_alive():
                    active_jobs.pop(i)
                    i -= 1
                    continue

                if current_time - last_start_time >= rate_limit_window_ms / 1000:
                    rate_limit_queue.append(current_time)
                    last_start_time = current_time

                if len(active_jobs) < max_concurrent:
                    if not rate_limit_queue or current_time - rate_limit_queue[0] >= rate_limit_window_ms / 1000:
                        job, job_vars = job_queue.popleft()
                        job_start_time = time.time()
                        active_jobs.append(threading.Thread(
                            target=lambda: process_job(job, job_vars, cache)
                        ))
                        active_jobs[-1].start()
                        rate_limit_queue.popleft()

        time.sleep(0.001)

    return cache

def process_job(job: Dict[str, str], job_vars: Dict[str, int], cache: Dict[str, Dict[str, str]]) -> None:
    result = run_job(job, job_vars, cache)
    save_cache(cache)
    print(json.dumps(result))

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('jobs_file', type=str, help='Path to JSON file containing job objects')
    args = parser.parse_args()

    with open(args.jobs_file, 'r') as f:
        jobs = json.load(f)

    results = process_jobs(jobs)
    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()

import argparse
import json
import os
import subprocess
import threading
import time
from collections import deque
from hashlib import sha256
import re

def generate_content_id(command):
    return sha256(command.encode()).hexdigest()[:32].lower()

def evaluate_delay(job, delay_str):
    expr = re.sub(r'\{\{([^}]+)\}\}', lambda m: str(job[m.group(0).split()[1]]), delay_str)
    try:
        return int(eval(expr))
    except:
        return 0

def run_job(job, cache):
    content_id = generate_content_id(job['command'])
    if content_id in cache:
        return cache[content_id]

    delay_ms = evaluate_delay(job, job['delay'])
    time.sleep(delay_ms / 1000.0)

    try:
        result = subprocess.run(
            job['command'],
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        cache[content_id] = {
            'exit_code': result.returncode,
            'output': result.stdout + result.stderr
        }
        return {
            'id': job['id'],
            'command': job['command'],
            'delay_ms': delay_ms,
            'exit_code': result.returncode,
            'output': result.stdout + result.stderr,
            'content_id': content_id
        }
    except Exception as e:
        cache[content_id] = {
            'exit_code': -1,
            'output': str(e)
        }
        return {
            'id': job['id'],
            'command': job['command'],
            'delay_ms': delay_ms,
            'exit_code': -1,
            'output': str(e),
            'content_id': content_id
        }

def job_runner():
    parser = argparse.ArgumentParser()
    parser.add_argument('jobs_file')
    args = parser.parse_args()

    with open(args.jobs_file) as f:
        jobs = json.load(f)

    cache_file = 'job_cache.json'
    if os.path.exists(cache_file):
        with open(cache_file) as f:
            cache = json.load(f)
    else:
        cache = {}

    job_queue = deque()
    active_jobs = []
    last_start_time = time.time()
    max_active = 4
    max_start_rate = 1000  # milliseconds

    def worker():
        while True:
            if not job_queue:
                time.sleep(0.1)
                continue

            job = job_queue.popleft()
            result = run_job(job, cache)

            with open(cache_file, 'w') as f:
                json.dump(cache, f)

            print(json.dumps(result))

            if len(active_jobs) < max_active:
                active_jobs.append(result)
            else:
                oldest_start = min(a['delay_ms'] for a in active_jobs)
                oldest_end = time.time() + oldest_start / 1000.0
                if time.time() < oldest_end:
                    time.sleep((oldest_end - time.time()) * 1000)
                else:
                    active_jobs.pop(0)

            if len(active_jobs) >= max_active:
                time_diff = time.time() - last_start_time
                if time_diff < max_start_rate / 1000.0:
                    time.sleep((max_start_rate / 1000.0) - time_diff)

    threads = []
    for _ in range(min(4, len(jobs))):
        t = threading.Thread(target=worker)
        t.start()
        threads.append(t)

    for job in jobs:
        job_queue.append(job)

    for t in threads:
        t.join()

if __name__ == '__main__':
    job_runner()
